-- Adhunik ERP - Phase 6A Packing Lists, carton planning and package management
begin;
alter table public.numbering_configurations drop constraint if exists numbering_configurations_entity_type_check;
alter table public.numbering_configurations add constraint numbering_configurations_entity_type_check check(entity_type in('EMPLOYEE','CUSTOMER','INQUIRY','ORDER','PROFORMA_INVOICE','PACKING_LIST'));
insert into public.numbering_configurations(entity_type,prefix,padding,separator,include_financial_year)values('PACKING_LIST','PL',4,'/',true)on conflict(entity_type)do nothing;
create table public.package_types(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null unique,category text not null check(category in('CARTON','BOX','WOODEN_BOX','CRATE','BUNDLE','PALLET','OTHER')),default_length_mm numeric(18,3) check(default_length_mm is null or default_length_mm>0),default_breadth_mm numeric(18,3) check(default_breadth_mm is null or default_breadth_mm>0),default_height_mm numeric(18,3) check(default_height_mm is null or default_height_mm>0),max_weight_kg numeric(18,3) check(max_weight_kg is null or max_weight_kg>0),is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),created_by uuid references auth.users(id)default auth.uid(),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id)default auth.uid());
insert into public.package_types(code,name,category,default_length_mm,default_breadth_mm,default_height_mm,sort_order)values('SMALL','Small Carton','CARTON',300,250,200,10),('MEDIUM','Medium Carton','CARTON',500,400,300,20),('LARGE','Large Carton','CARTON',700,500,450,30),('WOOD','Wooden Box','WOODEN_BOX',null,null,null,40),('CUSTOM','Custom / Other','OTHER',null,null,null,50);
create table public.packing_lists(id uuid primary key default gen_random_uuid(),packing_list_number text not null unique,pi_id uuid not null references public.proforma_invoices(id),order_id uuid not null references public.orders(id),company_id uuid not null references public.customer_companies(id),packing_date date not null default current_date,customer_name_snapshot text not null,pi_number_snapshot text not null,order_number_snapshot text not null,customer_po_number_snapshot text,project_name_snapshot text,shipping_address_snapshot jsonb not null,status text not null default 'DRAFT' check(status in('DRAFT','FINALIZED','DISPATCHED','CANCELLED')),remarks text,utilization_target_percentage numeric(7,3)check(utilization_target_percentage is null or utilization_target_percentage between 1 and 100),total_packages integer not null default 0,total_net_weight numeric(18,3)not null default 0,total_gross_weight numeric(18,3)not null default 0,total_volume_mm3 numeric(30,3)not null default 0,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),finalized_by uuid references auth.users(id),finalized_at timestamptz,reopened_by uuid references auth.users(id),reopened_at timestamptz,reopen_reason text,cancelled_by uuid references auth.users(id),cancelled_at timestamptz,cancellation_reason text,check(total_packages>=0 and total_net_weight>=0 and total_gross_weight>=total_net_weight and total_volume_mm3>=0),check(status<>'FINALIZED'or(finalized_by is not null and finalized_at is not null)),check(status<>'CANCELLED'or(cancelled_by is not null and cancelled_at is not null and nullif(trim(cancellation_reason),'')is not null)));
create table public.packing_list_items(id uuid primary key default gen_random_uuid(),packing_list_id uuid not null references public.packing_lists(id)on delete cascade,pi_item_id uuid not null references public.proforma_invoice_items(id),line_number integer not null,item_name_snapshot text,item_description_snapshot text not null,model_snapshot text,hsn_snapshot text,unit_snapshot text not null,pi_quantity numeric(18,4)not null check(pi_quantity>0),current_packing_quantity numeric(18,4)not null default 0 check(current_packing_quantity>=0),item_length_mm numeric(18,3)check(item_length_mm is null or item_length_mm>=0),item_breadth_mm numeric(18,3)check(item_breadth_mm is null or item_breadth_mm>=0),item_height_mm numeric(18,3)check(item_height_mm is null or item_height_mm>=0),item_volume_mm3 numeric(30,3)generated always as(coalesce(item_length_mm,0)*coalesce(item_breadth_mm,0)*coalesce(item_height_mm,0))stored,remarks text,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(packing_list_id,pi_item_id));
create table public.packing_list_packages(id uuid primary key default gen_random_uuid(),packing_list_id uuid not null references public.packing_lists(id)on delete cascade,package_number integer not null check(package_number>0),package_type_id uuid references public.package_types(id),package_type_snapshot text not null,length_mm numeric(18,3)not null check(length_mm>0),breadth_mm numeric(18,3)not null check(breadth_mm>0),height_mm numeric(18,3)not null check(height_mm>0),volume_mm3 numeric(30,3)generated always as(length_mm*breadth_mm*height_mm)stored,net_weight_kg numeric(18,3)check(net_weight_kg is null or net_weight_kg>=0),gross_weight_kg numeric(18,3)check(gross_weight_kg is null or gross_weight_kg>=0),remarks text,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(gross_weight_kg is null or net_weight_kg is null or gross_weight_kg>=net_weight_kg),unique(packing_list_id,package_number));
create table public.packing_list_package_contents(id uuid primary key default gen_random_uuid(),package_id uuid not null references public.packing_list_packages(id)on delete cascade,packing_list_item_id uuid not null references public.packing_list_items(id)on delete cascade,quantity numeric(18,4)not null check(quantity>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(package_id,packing_list_item_id));
create table public.packing_list_activities(id uuid primary key default gen_random_uuid(),packing_list_id uuid not null references public.packing_lists(id),activity_type text not null,description text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
insert into public.numbering_counters(entity_type,current_value)values('PACKING_LIST',0)on conflict(entity_type)do nothing;
create index packing_lists_pi on public.packing_lists(pi_id,created_at desc);create index packing_lists_order on public.packing_lists(order_id);create index packing_lists_company on public.packing_lists(company_id);create index packing_lists_status_date on public.packing_lists(status,packing_date desc);create index packing_lists_creator on public.packing_lists(created_by);create index packing_items_parent on public.packing_list_items(packing_list_id);create index packing_items_pi_item on public.packing_list_items(pi_item_id);create index packing_packages_parent on public.packing_list_packages(packing_list_id);create index packing_contents_package on public.packing_list_package_contents(package_id);create index packing_contents_item on public.packing_list_package_contents(packing_list_item_id);create index packing_activities_parent on public.packing_list_activities(packing_list_id,created_at desc);
create function public.can_view_packing_list(p_id uuid)returns boolean language sql stable security definer set search_path = '' as $$select exists(select 1 from public.packing_lists p where p.id=p_id and public.can_view_proforma_invoice(p.pi_id))$$;
create function public.can_manage_packing_list(p_id uuid)returns boolean language sql stable security definer set search_path = '' as $$select exists(select 1 from public.packing_lists p where p.id=p_id and p.status='DRAFT'and(public.can_manage_crm()or p.created_by=auth.uid()))$$;
create function public.create_packing_list(p_pi_id uuid)returns uuid language plpgsql security definer set search_path = '' as $$declare p public.proforma_invoices%rowtype;o public.orders%rowtype;v uuid;begin select *into p from public.proforma_invoices where id=p_pi_id and status in('ISSUED','ACCEPTED')and deleted_at is null and public.can_view_proforma_invoice(id);if not found then raise exception 'Only an accessible Issued or Accepted PI can be packed';end if;select *into o from public.orders where id=p.order_id;insert into public.packing_lists(packing_list_number,pi_id,order_id,company_id,customer_name_snapshot,pi_number_snapshot,order_number_snapshot,customer_po_number_snapshot,project_name_snapshot,shipping_address_snapshot,created_by,updated_by)values(public.allocate_business_number('PACKING_LIST'),p.id,p.order_id,p.company_id,p.customer_name_snapshot,p.pi_number,o.order_number,p.customer_po_number,p.project_name,p.shipping_address_snapshot,auth.uid(),auth.uid())returning id into v;insert into public.packing_list_items(packing_list_id,pi_item_id,line_number,item_name_snapshot,item_description_snapshot,model_snapshot,hsn_snapshot,unit_snapshot,pi_quantity,sort_order)select v,id,line_number,item_name,item_description,model_type,hsn_code,unit,quantity,sort_order from public.proforma_invoice_items where proforma_invoice_id=p.id;insert into public.packing_list_activities values(default,v,'CREATED','Packing List created from PI '||p.pi_number,auth.uid(),default);return v;end; $$;
create function public.save_packing_list(p_id uuid,p_data jsonb,p_items jsonb,p_packages jsonb)returns void language plpgsql security definer set search_path = '' as $$declare i jsonb;k jsonb;c jsonb;iid uuid;kid uuid;q numeric;begin perform 1 from public.packing_lists where id=p_id and public.can_manage_packing_list(id)for update;if not found then raise exception 'Draft Packing List not editable';end if;update public.packing_lists set packing_date=coalesce(nullif(p_data->>'packing_date','')::date,packing_date),shipping_address_snapshot=coalesce(p_data->'shipping_address',shipping_address_snapshot),remarks=nullif(p_data->>'remarks',''),utilization_target_percentage=nullif(p_data->>'utilization_target_percentage','')::numeric,updated_by=auth.uid(),updated_at=now()where id=p_id;for i in select value from jsonb_array_elements(p_items)loop iid:=(i->>'id')::uuid;q:=coalesce(nullif(i->>'quantity','')::numeric,0);update public.packing_list_items set current_packing_quantity=q,item_description_snapshot=coalesce(nullif(trim(i->>'description'),''),item_description_snapshot),item_length_mm=nullif(i->>'length_mm','')::numeric,item_breadth_mm=nullif(i->>'breadth_mm','')::numeric,item_height_mm=nullif(i->>'height_mm','')::numeric,remarks=nullif(i->>'remarks',''),updated_at=now()where id=iid and packing_list_id=p_id and q between 0 and pi_quantity;if not found then raise exception 'Invalid item or quantity';end if;end loop;delete from public.packing_list_packages where packing_list_id=p_id;for k in select value from jsonb_array_elements(p_packages)loop insert into public.packing_list_packages(packing_list_id,package_number,package_type_id,package_type_snapshot,length_mm,breadth_mm,height_mm,net_weight_kg,gross_weight_kg,remarks,sort_order)values(p_id,(k->>'package_number')::int,nullif(k->>'package_type_id','')::uuid,k->>'package_type_snapshot',(k->>'length_mm')::numeric,(k->>'breadth_mm')::numeric,(k->>'height_mm')::numeric,nullif(k->>'net_weight_kg','')::numeric,nullif(k->>'gross_weight_kg','')::numeric,nullif(k->>'remarks',''),coalesce((k->>'sort_order')::int,0))returning id into kid;for c in select value from jsonb_array_elements(coalesce(k->'contents','[]'))loop iid:=(c->>'packing_list_item_id')::uuid;if not exists(select 1 from public.packing_list_items where id=iid and packing_list_id=p_id)then raise exception 'Invalid package item';end if;insert into public.packing_list_package_contents(package_id,packing_list_item_id,quantity)values(kid,iid,(c->>'quantity')::numeric);end loop;end loop;if exists(select 1 from public.packing_list_items i where i.packing_list_id=p_id and coalesce((select sum(c.quantity)from public.packing_list_package_contents c join public.packing_list_packages k on k.id=c.package_id where c.packing_list_item_id=i.id),0)>i.current_packing_quantity)then raise exception 'Package allocation exceeds packing quantity';end if;update public.packing_lists p set total_packages=(select count(*)from public.packing_list_packages where packing_list_id=p.id),total_net_weight=coalesce((select sum(coalesce(net_weight_kg,0))from public.packing_list_packages where packing_list_id=p.id),0),total_gross_weight=coalesce((select sum(coalesce(gross_weight_kg,0))from public.packing_list_packages where packing_list_id=p.id),0),total_volume_mm3=coalesce((select sum(volume_mm3)from public.packing_list_packages where packing_list_id=p.id),0)where id=p_id;insert into public.packing_list_activities values(default,p_id,'EDITED','Draft Packing List updated',auth.uid(),default);end; $$;

create function public.finalize_packing_list(p_id uuid)returns void language plpgsql security definer set search_path = '' as $$declare vpi uuid;r record;begin select pi_id into vpi from public.packing_lists where id=p_id and public.can_manage_packing_list(id)for update;if not found then raise exception 'Draft Packing List not editable';end if;perform pg_advisory_xact_lock(hashtextextended(vpi::text,0));if not exists(select 1 from public.proforma_invoices where id=vpi and status in('ISSUED','ACCEPTED'))then raise exception 'PI is not eligible';end if;if not exists(select 1 from public.packing_list_items where packing_list_id=p_id and current_packing_quantity>0)then raise exception 'Select a packing quantity';end if;for r in select i.id,i.pi_item_id,i.pi_quantity,i.current_packing_quantity,coalesce((select sum(x.current_packing_quantity)from public.packing_list_items x join public.packing_lists p on p.id=x.packing_list_id where x.pi_item_id=i.pi_item_id and p.status='FINALIZED'and p.id<>p_id),0)packed,coalesce((select sum(c.quantity)from public.packing_list_package_contents c join public.packing_list_packages k on k.id=c.package_id where c.packing_list_item_id=i.id and k.packing_list_id=p_id),0)allocated from public.packing_list_items i where i.packing_list_id=p_id loop if r.packed+r.current_packing_quantity>r.pi_quantity then raise exception 'Packing exceeds remaining PI balance';end if;if r.allocated<>r.current_packing_quantity then raise exception 'Every packing quantity must be fully allocated';end if;end loop;if exists(select 1 from public.packing_list_package_contents c join public.packing_list_packages k on k.id=c.package_id join public.packing_list_items i on i.id=c.packing_list_item_id where k.packing_list_id=p_id and i.item_volume_mm3>0 group by k.id,k.volume_mm3 having sum(c.quantity*i.item_volume_mm3)>k.volume_mm3)then raise exception 'Allocated theoretical item volume exceeds package volume';end if;if exists(select 1 from public.packing_list_package_contents c join public.packing_list_packages k on k.id=c.package_id join public.packing_list_items i on i.id=c.packing_list_item_id where k.packing_list_id=p_id and i.item_length_mm>0 and i.item_breadth_mm>0 and i.item_height_mm>0 and not((i.item_length_mm<=k.length_mm and i.item_breadth_mm<=k.breadth_mm and i.item_height_mm<=k.height_mm)or(i.item_length_mm<=k.length_mm and i.item_height_mm<=k.breadth_mm and i.item_breadth_mm<=k.height_mm)or(i.item_breadth_mm<=k.length_mm and i.item_length_mm<=k.breadth_mm and i.item_height_mm<=k.height_mm)or(i.item_breadth_mm<=k.length_mm and i.item_height_mm<=k.breadth_mm and i.item_length_mm<=k.height_mm)or(i.item_height_mm<=k.length_mm and i.item_length_mm<=k.breadth_mm and i.item_breadth_mm<=k.height_mm)or(i.item_height_mm<=k.length_mm and i.item_breadth_mm<=k.breadth_mm and i.item_length_mm<=k.height_mm)))then raise exception 'Item dimensions exceed package dimensions';end if;update public.packing_lists set status='FINALIZED',finalized_by=auth.uid(),finalized_at=now(),updated_by=auth.uid(),updated_at=now()where id=p_id;insert into public.packing_list_activities values(default,p_id,'FINALIZED','Packing List finalized',auth.uid(),default);end; $$;
create function public.reopen_packing_list(p_id uuid,p_reason text)returns void language plpgsql security definer set search_path = '' as $$begin if not public.can_manage_crm()or nullif(trim(p_reason),'')is null then raise exception 'Admin or Manager and reason required';end if;update public.packing_lists set status='DRAFT',reopened_by=auth.uid(),reopened_at=now(),reopen_reason=trim(p_reason),finalized_by=null,finalized_at=null,updated_by=auth.uid(),updated_at=now()where id=p_id and status='FINALIZED';if not found then raise exception 'Finalized Packing List not found';end if;insert into public.packing_list_activities values(default,p_id,'REOPENED','Reopened: '||trim(p_reason),auth.uid(),default);end; $$;
create function public.cancel_packing_list(p_id uuid,p_reason text)returns void language plpgsql security definer set search_path = '' as $$begin if nullif(trim(p_reason),'')is null then raise exception 'Cancellation reason required';end if;update public.packing_lists set status='CANCELLED',cancelled_by=auth.uid(),cancelled_at=now(),cancellation_reason=trim(p_reason),updated_by=auth.uid(),updated_at=now()where id=p_id and status in('DRAFT','FINALIZED')and(public.can_manage_crm()or created_by=auth.uid());if not found then raise exception 'Packing List not cancellable';end if;insert into public.packing_list_activities values(default,p_id,'CANCELLED','Cancelled: '||trim(p_reason),auth.uid(),default);end; $$;
create function public.protect_packing_list()returns trigger language plpgsql security definer set search_path = '' as $$begin new.packing_list_number=old.packing_list_number;new.pi_id=old.pi_id;new.order_id=old.order_id;new.company_id=old.company_id;new.created_by=old.created_by;new.created_at=old.created_at;if old.status in('CANCELLED','DISPATCHED')then raise exception 'Locked Packing List cannot be edited';end if;return new;end; $$;
create trigger protect_packing_list before update on public.packing_lists for each row execute function public.protect_packing_list();create trigger package_types_updated before update on public.package_types for each row execute function public.set_updated_at();create function public.set_packing_child_updated_at()returns trigger language plpgsql set search_path = '' as $$begin new.updated_at=now();return new;end; $$;create trigger packing_items_updated before update on public.packing_list_items for each row execute function public.set_packing_child_updated_at();create trigger packing_packages_updated before update on public.packing_list_packages for each row execute function public.set_packing_child_updated_at();create trigger packing_contents_updated before update on public.packing_list_package_contents for each row execute function public.set_packing_child_updated_at();
alter table public.package_types enable row level security;alter table public.packing_lists enable row level security;alter table public.packing_list_items enable row level security;alter table public.packing_list_packages enable row level security;alter table public.packing_list_package_contents enable row level security;alter table public.packing_list_activities enable row level security;
create policy "ERP read package types"on public.package_types for select to authenticated using(public.has_active_erp_access());create policy "Admin manage package types"on public.package_types for all to authenticated using(public.is_erp_admin())with check(public.is_erp_admin());create policy "Packing Lists visible"on public.packing_lists for select to authenticated using(public.can_view_packing_list(id));create policy "Packing items visible"on public.packing_list_items for select to authenticated using(public.can_view_packing_list(packing_list_id));create policy "Packing packages visible"on public.packing_list_packages for select to authenticated using(public.can_view_packing_list(packing_list_id));create policy "Packing contents visible"on public.packing_list_package_contents for select to authenticated using(public.can_view_packing_list((select packing_list_id from public.packing_list_packages where id=package_id)));create policy "Packing activities visible"on public.packing_list_activities for select to authenticated using(public.can_view_packing_list(packing_list_id));
grant select on public.package_types,public.packing_lists,public.packing_list_items,public.packing_list_packages,public.packing_list_package_contents,public.packing_list_activities to authenticated;grant insert,update on public.package_types to authenticated;revoke all on function public.create_packing_list(uuid),public.save_packing_list(uuid,jsonb,jsonb,jsonb),public.finalize_packing_list(uuid),public.reopen_packing_list(uuid,text),public.cancel_packing_list(uuid,text)from public,anon;grant execute on function public.can_view_packing_list(uuid),public.can_manage_packing_list(uuid),public.create_packing_list(uuid),public.save_packing_list(uuid,jsonb,jsonb,jsonb),public.finalize_packing_list(uuid),public.reopen_packing_list(uuid,text),public.cancel_packing_list(uuid,text)to authenticated;
commit;
